import React, { createContext, useContext, useState, ReactNode } from 'react';

interface BookingContextType {
  isOpen: boolean;
  openBooking: (details?: string) => void;
  closeBooking: () => void;
  bookingDetails: string;
}

const BookingContext = createContext<BookingContextType | undefined>(undefined);

export const BookingProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [bookingDetails, setBookingDetails] = useState('');

  const openBooking = (details = '') => {
    setBookingDetails(details);
    setIsOpen(true);
  };

  const closeBooking = () => {
    setIsOpen(false);
    setBookingDetails('');
  };

  return (
    <BookingContext.Provider value={{ isOpen, openBooking, closeBooking, bookingDetails }}>
      {children}
    </BookingContext.Provider>
  );
};

export const useBooking = () => {
  const context = useContext(BookingContext);
  if (!context) throw new Error('useBooking must be used within a BookingProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { X, CheckCircle2, Loader2, MessageSquare } from 'lucide-react';
import { useBooking } from '../contexts/BookingContext';
import { CONTACT_INFO } from '../constants';
import Button from './Button';

const BookingModal: React.FC = () => {
  const { isOpen, closeBooking, bookingDetails } = useBooking();
  const [step, setStep] = useState<'form' | 'processing' | 'success'>('form');
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');

  // Reset state when modal opens
  useEffect(() => {
    if (isOpen) {
      setStep('form');
      setPhone('');
      setName('');
    }
